def InsertionSort(DataArray):  
    if (len(DataArray)) <= 1: 
        return DataArray 
    for X in range(1, len(DataArray)):  
        CurrentValue = DataArray[X] 
        Y = X-1 
        while Y >=0 and CurrentValue < DataArray[Y]:  
            DataArray[Y+1] = DataArray[Y] 
            Y = Y -1 
        DataArray[Y+1] = CurrentValue  
    return DataArray 

