def Search(DataArray, ItemToFind):  
    Low = 0 
    High = len(DataArray) - 1  
    Middle = 0 

    while Low <= High: 
        Middle = (High + Low) // 2 
        if DataArray[Middle] < ItemToFind: 
            Low = Middle + 1 
        elif DataArray[Middle] > ItemToFind: 
            High = Middle - 1  
        else: 
            return Middle  
    return -1 

