public static Integer Search(Integer[] DataArray, Integer ItemToFind){  
     Integer Low = 0; 
     Integer High = DataArray.length - 1;  
     Integer Middle = 0; 
     while(Low <= High){ 
          Middle = (High + Low) / 2;  
          if(DataArray[Middle] < ItemToFind){ 
               Low = Middle + 1; 
          }else if(DataArray[Middle] > ItemToFind){ 
               High = Middle - 1; 
          }else{ 
               return Middle; 
          } 
     } 
     return -1; 
}

